apshot(payload.payment.accountId)   // reads Domain Model\n\n        // Delegate to the generic rule-based service.\n        val base = ruleBased.validate(ctx, payload).bind()\n\n        // Post-rule: stamp the snapshot id into the typed result.\n        base.copy(customerSnapshotId = snapshot.id)\n    }\n}\n'})}),"\n",(0,r.jsxs)(n.p,{children:["Because this impl declares ",(0,r.jsx)(n.code,{children:'@PaymentVariant(market = "GB", accountType = CORPORATE)'})," (specificity 6), it outscores the generic (specificity 0) for ",(0,r.jsx)(n.code,{children:"(*, GB, CORPORATE, *, *)"})," contexts. All ",(0,r.jsx)(n.code,{children:"(GB, CORPORATE, *)"})," rulebooks are still resolved via ",(0,r.jsx)(n.code,{children:"rulebooks.lookup(ctx)"})," ",(0,r.jsx)(n.em,{children:"inside"})," this impl \u2014 the hybrid keeps the rulebook fan-out while adding one piece of bespoke per-",(0,r.jsx)(n.code,{children:"(market, accountType)"})," logic."]}),"\n",(0,r.jsx)(n.h3,{id:"variation-3--fully-custom-escape-hatch",children:"Variation 3 \u2014 Fully custom (escape hatch)"}),"\n",(0,r.jsx)(n.p,{children:"Used when the logic genuinely cannot be expressed as a sequential chain \u2014 e.g. iterating over installment legs, each with its own client checks, where any leg failure aborts the whole payment."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-kotlin",children:'@ApplicationScoped\n@PaymentVariant(market = "MX", accountType = AccountType.CORPORATE)\nclass PaymentValidationServiceMXCorporate : PaymentValidationService {\n\n    override suspend fun validate(\n        ctx: PaymentContext,\n        payload: PaymentPayload,\n    ): Either<ValidationFailure, ValidatedPaymentResult> = either {\n        val legs = (payload.payment as PendingPayment).installmentLegs       // from Domain Model\n\n        ensure(legs.isNotEmpty()) {\n            ValidationFailure("legs-required", "EMPTY_INSTALLMENTS",\n                              "MX Corporate requires at least one installment leg")\n        }\n\n        val instruments = Workflow.newActivityStub(\n            InstrumentsClientActivity::class.java,\n            ActivityOptions.newBuilder().setStartToCloseTimeout(Duration.ofSeconds(2)).build(),\n        )\n        val options = Workflow.newActivityStub(\n            PaymentOptionsClientActivity::class.java,\n            ActivityOptions.newBuilder().setStartToCloseTimeout(Duration.ofSeconds(2)).build(),\n        )\n\n        var totalAmount = Money.zero(MXN)\n        for ((idx, leg) in legs.withIndex()) {\n            ensure(instruments.isValid(leg.instrumentId)) {\n                ValidationFailure("leg-$idx-instrument", "LEG_INSTRUMENT_INVALID",\n                                  "leg $idx instrument invalid")\n            }\n\n            ensure(options.isAllowed(leg.instrumentId, leg.optionCode)) {\n                ValidationFailure("leg-$idx-option", "LEG_OPTION_DISALLOWED",\n                                  "leg $idx option ${leg.optionCode} not allowed")\n            }\n\n            totalAmount += leg.amount\n        }\n\n        ValidatedPaymentResult(\n            validatedAt = Clock.systemUTC().instant(),\n            rulesPassed = listOf("mx-multi-leg-validation"),\n            mandateId   = null,\n        )\n    }\n}\n'})}),"\n",(0,r.jsxs)(n.p,{children:["This impl ignores the rulebook entirely \u2014 the variance lives inside its own code. It is still discovered by KSP via ",(0,r.jsx)(n.code,{children:"@PaymentVariant"}),", still picked by the same ",(0,r.jsx)(n.a,{href:"/billpay-wiki/docs/build/services/proposal/variant-resolution#the-serviceresolver",children:(0,r.jsx)(n.code,{children:"ServiceResolver"})})," (specificity 6 beats generic 0), and still receives a ",(0,r.jsx)(n.code,{children:"PaymentPayload"})," produced by the workflow's orchestration plan. The escape hatch costs nothing structural \u2014 only the rule-DSL ergonomics are lost for this one impl."]}),"\n",(0,r.jsx)(n.h3,{id:"when-to-pick-which",childr